-- Forever STUwave: the totem preset cells (look, tooltips, editor)
--
-- The design mockup, drawn on the two cells TotemPresets.lua adds to the totem tab. This
-- file is the picture and the controls; the rules (presets, colours, the step record) are TotemPresets.lua's.
--
--   * A CELL is a 38 px totem tab button wearing a ring: one arc per totem of its preset, in drop order, each in its
--     element's colour (the textures are generated by tools/assets/generate_totem_dial.py: one texture per arc and look,
--     all the size of the button, tinted here). The slot's number sits in the middle, a "+" for a slot with nothing in it.
--     While a step runs the arcs that dropped glow, the next one is thick with a white core and its totem's icon replaces
--     the number, and cyan brackets stand round the cell.
--   * The OUTLINE COLOUR (one of seven, chosen per slot in the editor) draws the cut border, the glow, the underline and
--     the name label of the cell; the arcs stay in element colours. Hover takes the fill 16 percent toward that colour and
--     the glow to .6, a press 32 percent (the config window's convention). An UNSET slot is dim, dashed and muted, with a
--     "+" and the plate UNSET, and a press on it does nothing. There is no disabled look: the cells are always live.
--   * A name plate on the rail above the cell (the preset's name, the setting turns it off). A raised plate above that
--     shows the step count with a square for each totem ("2/4") while a step runs.
--   * The cell: click = the step (a secure attribute, written out of combat by ApplyCell, in the totem tab's Sync),
--     Shift click = edit the cell's preset (or make it from the four totem buttons when the slot is unset). Nothing here
--     writes a secure attribute in combat.
--   * The EDITOR is a plain card on UIParent (never secure, nothing secure anchored to it): the name (8 letters), the
--     outline swatches, the drop order with each row's totem and up and down arrows, CLEAR (asks twice). Clicking a row's
--     totem opens that element's list of known totems, or "left out". Every change saves at once; closing just hides it.
--     Editing is shut in combat: the card closes when combat starts and refuses clicks. Choosing a colour is gated like
--     any edit, but painting it is only vertex colours on plain textures, so it is legal in combat.
--
-- Only plain frames, textures and font strings are touched in combat. Loads after TotemPresets.lua. Nothing here is
-- verified in game.

local _, FS = ...

local Dial = {}
FS.TotemDial = Dial

local MEDIA = "Interface\\AddOns\\forever-stuwave\\Media\\Textures\\"

local D = {
    BTN = 38, CHAMFER = 5,
    RING_ARCS = 4,
    PLATE_H = 12, PLATE_RISE = 6, RAISE_H = 14, RAISE_RISE = 20,
    DASH = 3, DASH_THICK = 1.4, DASH_COUNT = 5,
    BRACKET = { OFF = 2.5, LEN = 6, THICK = 1.4 },
    TICK = 0.1,                 -- seconds between the ticker's looks
    -- The editor card, 218 x 252: 20 wider and taller than the first mockup's 198 x 232, so the close X (seated 5 in and 3 down)
    -- clears the name field (the old 20 down was inside the X's 3 + 15 tall plate and its halo). The extra height is 10 above the
    -- name field (the header row the X sits in), 2 of swatch size, and 2 on each of the four rows; the extra width is the swatch
    -- row's (seven of 22 on a pitch of 30 span the 202 inside the 8 margins) and the name field's, rows' and CLEAR's.
    -- TOP is where the first drop order row starts; the other Ys are the tops of the name field, the OUTLINE label, the
    -- swatches and the DROP ORDER label. A row is ROW - 4 tall (26 at one pixel per unit), so rounding to whole pixels at a
    -- scale that is not 1 still leaves a pixel between two rows.
    CARD = { W = 218, ROW = 29, ROWS = 4, TOP = 106, FOOT = 30,
             SWATCH = 22, PITCH = 30, SWATCH_Y = 66, NAME_Y = 30, OUTLINE_Y = 55, LABEL_Y = 94 },
    BTN_PAD = 14,               -- design px each side of the label of an editor button that sizes to its text (the config
                                -- window's buttons: width = text + 28)
    CONFIRM = 3,                -- seconds CLEAR stays armed
    CHOOSER_TILE = 26,
}
Dial.D = D

local Theme = FS.Theme

local function Presets() return FS.TotemPresets end
local function Totems() return FS.TotemBar end

local function Scale()
    return (FS.Layout and FS.Layout.Scale and FS.Layout.Scale()) or 1
end

local function InCombat()
    return InCombatLockdown and InCombatLockdown() and true or false
end

local function Color(name)
    local c = Theme[name]
    if type(c) == "table" then return c end
end

local CYAN = Color("COLOR_POWER") or { 0.133, 0.878, 1, 1 }
local PINK = Color("COLOR_HEALTH") or { 1, 0.18, 0.592, 1 }
local MUTED = Color("COLOR_MUTED") or { 0.6157, 0.5765, 0.7686, 1 }
local VIOLET = Color("COLOR_BORDER") or { 0.659, 0.333, 0.969, 1 }
local WHITE = { 1, 1, 1, 1 }
local ELEMENT = (type(Theme.COLOR_TOTEM) == "table" and Theme.COLOR_TOTEM) or {
    fire = { 1, 0.3529, 0.2353, 1 }, earth = { 0.6588, 0.8784, 0.3882, 1 },
    water = { 0.2902, 0.6588, 1, 1 }, air = { 0.8863, 0.8314, 1, 1 },
}
local ELEMENT_NAME = { fire = "Fire", earth = "Earth", water = "Water", air = "Air" }

local function Tint(texture, c, a)
    if texture then texture:SetVertexColor(c[1], c[2], c[3], a == nil and (c[4] or 1) or a) end
end

local function Rgb255(c)
    return math.floor(c[1] * 255 + 0.5), math.floor(c[2] * 255 + 0.5), math.floor(c[3] * 255 + 0.5)
end

-- A colour swatch in a tooltip line (a tinted white square).
local function Swatch(c)
    local r, g, b = Rgb255(c)
    return string.format("|TInterface\\Buttons\\WHITE8X8:9:9:0:0:8:8:0:8:0:8:%d:%d:%d|t ", r, g, b)
end

-------------------------------------------------------------------------------
-- Small pieces: edges, dashes, a plate
-------------------------------------------------------------------------------

-- A one pixel ring of four edge textures on `frame`.
local function NewEdges(frame, layer, sub)
    local edges = {}
    for i = 1, 4 do edges[i] = frame:CreateTexture(nil, layer or "OVERLAY", nil, sub or 3) end
    return edges
end

-- Seats a ring of four edges on `frame`, `inset` units inside its border (0 = on it).
local function SeatEdges(edges, frame, thick, inset)
    local i = inset or 0
    edges[1]:ClearAllPoints()
    edges[1]:SetPoint("TOPLEFT", frame, "TOPLEFT", i, -i)
    edges[1]:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -i, -i)
    edges[1]:SetHeight(thick)
    edges[2]:ClearAllPoints()
    edges[2]:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", i, i)
    edges[2]:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -i, i)
    edges[2]:SetHeight(thick)
    edges[3]:ClearAllPoints()
    edges[3]:SetPoint("TOPLEFT", frame, "TOPLEFT", i, -i)
    edges[3]:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", i, i)
    edges[3]:SetWidth(thick)
    edges[4]:ClearAllPoints()
    edges[4]:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -i, -i)
    edges[4]:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -i, i)
    edges[4]:SetWidth(thick)
end

local function SetEdges(edges, c, a)
    for i = 1, #edges do edges[i]:SetColorTexture(c[1], c[2], c[3], a) end
end

-- The dashed edge of a button (4 sides, D.DASH_COUNT dashes each along the straight run between the chamfers), as a set of
-- textures on `host`. Returns { dashes }.
local function NewDashSet(host)
    local set = { dashes = {} }
    for i = 1, 4 * D.DASH_COUNT do
        local tex = host:CreateTexture(nil, "OVERLAY", nil, 4)
        tex:Hide()
        set.dashes[i] = tex
    end
    return set
end

-- Seats the set on `anchor` (design size w x h at scale s). Dashes run from the chamfer to the chamfer.
local function SeatDashSet(set, anchor, w, h, s)
    local run, cut = w - 2 * D.CHAMFER, D.CHAMFER
    local step = (run - D.DASH) / (D.DASH_COUNT - 1)
    local n = 0
    local function place(x, y, dw, dh)
        n = n + 1
        local tex = set.dashes[n]
        tex:ClearAllPoints()
        tex:SetPoint("TOPLEFT", anchor, "TOPLEFT", x * s, -y * s)
        tex:SetSize(dw * s, dh * s)
    end
    for k = 0, D.DASH_COUNT - 1 do
        local at = cut + k * step
        place(at, 0.4, D.DASH, D.DASH_THICK)                       -- top
        place(w - D.DASH_THICK - 0.4, at, D.DASH_THICK, D.DASH)    -- right
        place(at, h - D.DASH_THICK - 0.4, D.DASH, D.DASH_THICK)    -- bottom
        place(0.4, at, D.DASH_THICK, D.DASH)                       -- left
    end
end

local function PaintDashSet(set, c, a, show)
    for _, tex in ipairs(set.dashes) do
        tex:SetColorTexture(c[1], c[2], c[3], a)
        if show then tex:Show() else tex:Hide() end
    end
end

-- The plate: a dark fill with a one pixel border, a text, and up to four squares (the step count).
local function NewPlate(parent, level)
    local plate = CreateFrame("Frame", nil, parent)
    if plate.SetFrameLevel and parent.GetFrameLevel then plate:SetFrameLevel(parent:GetFrameLevel() + level) end
    plate.fill = plate:CreateTexture(nil, "BACKGROUND")
    plate.fill:SetAllPoints(plate)
    plate.fill:SetColorTexture(0.051, 0.024, 0.125, 0.94)
    plate.edges = NewEdges(plate, "BORDER", 0)
    plate.text = plate:CreateFontString(nil, "OVERLAY")
    plate.squares = {}
    for i = 1, D.RING_ARCS do
        local sq = plate:CreateTexture(nil, "OVERLAY", nil, 2)
        sq:Hide()
        plate.squares[i] = sq
    end
    plate:Hide()
    return plate
end

-- Fills a plate: `text` in `c`, squares `{ { c, state } ... }` before it (done 1, next .55, wait .2), right aligned at
-- (0, 0) of its anchor or centred, at design size. Returns nothing; the caller anchors it.
local function SetPlate(plate, o, s)
    local text = o.text or ""
    local sq = o.squares or {}
    local pw = #sq > 0 and (#sq * 7 + 4) or 0
    local w = (o.wide and (#text * 6.7 + 10) or (#text * 6.1 + 7)) + pw
    local h = o.height
    plate:SetSize(w * s, h * s)
    SeatEdges(plate.edges, plate, math.max(1, s))
    SetEdges(plate.edges, o.color, o.edgeAlpha or 0.9)
    Theme.ApplyMono(plate.text, math.floor((o.wide and 11 or 10) * s + 0.5), o.textColor or WHITE)
    plate.text:ClearAllPoints()
    plate.text:SetPoint("LEFT", plate, "LEFT", (o.wide and 5 or 3.5) * s + pw * s, 0)
    plate.text:SetText(text)
    for i, square in ipairs(plate.squares) do
        local item = sq[i]
        if item then
            local c, state = item[1], item[2]
            square:ClearAllPoints()
            square:SetPoint("LEFT", plate, "LEFT", (4 + (i - 1) * 7) * s, 0)
            square:SetSize(5 * s, 5 * s)
            square:SetColorTexture(c[1], c[2], c[3], state == "done" and 1 or state == "next" and 0.55 or 0.2)
            square:Show()
        else
            square:Hide()
        end
    end
    plate:Show()
end

-------------------------------------------------------------------------------
-- A cell's state, from the rules
-------------------------------------------------------------------------------

-- What a cell shows right now, apart from where and how it is drawn:
-- { cell, slot, preset, name, digit, color, arcs = { { element, entry, locked, state } }, k, total, stepping, next (the
--   entry about to drop), empty }
function Dial.StateOf(cell)
    local PS = Presets()
    local st = { cell = cell, arcs = {}, k = 0, total = 0 }
    local slot = PS.SlotOf(cell)
    local preset = PS.CellPreset(cell)
    st.slot, st.preset = slot, preset
    st.color = PS.ColorRgb(slot) or CYAN
    st.name = preset and preset.name or "UNSET"
    local entries = PS.Entries(preset)
    local k, total = PS.Progress(cell)
    st.k, st.total = k, total
    st.stepping = k > 0
    local j = 0
    for _, entry in ipairs(entries) do
        local item = { element = entry.element, entry = entry, locked = not entry.known }
        if not entry.known then
            item.state = "locked"
        elseif not st.stepping then
            item.state = "idle"
        elseif j < k then
            item.state = "done"
            j = j + 1
        elseif j == k then
            item.state = "next"
            st.next = entry
            j = j + 1
        else
            item.state = "wait"
            j = j + 1
        end
        st.arcs[#st.arcs + 1] = item
    end
    st.empty = #entries == 0 or not preset
    st.digit = st.empty and "+" or tostring(slot)
    return st
end

-------------------------------------------------------------------------------
-- Building a cell (once per button, re-seated on every scale)
-------------------------------------------------------------------------------

local function ArcPath(n, i, kind)
    return MEDIA .. "totem_dial_n" .. n .. "_" .. i .. "_" .. kind .. ".tga"
end

local Paint

local function OnEnter(self)
    self.fsHover = true
    Paint(self)
end

local function OnLeave(self)
    self.fsHover, self.fsPressed = false, false
    Paint(self)
end

local function OnMouseDown(self)
    self.fsPressed = true
    Paint(self)
end

local function OnMouseUp(self)
    self.fsPressed = false
    Paint(self)
end

-- The cell was hidden under the mouse (its setting went off): no hover or press is left behind.
local function OnHide(self)
    self.fsHover, self.fsPressed = false, false
end

-- A click event that counts as a press of the cell: the one the secure click acts on (the key down when the client
-- acts on key down, the release otherwise).
local function IsPressEvent(down)
    local useDown = false
    if C_CVar and C_CVar.GetCVar then
        local ok, value = pcall(C_CVar.GetCVar, "ActionButtonUseKeyDown")
        useDown = ok and value == "1"
    end
    return (down and true or false) == useDown
end

local function ShiftDown()
    return IsShiftKeyDown and IsShiftKeyDown() and true or false
end

local function AltDown()
    return IsAltKeyDown and IsAltKeyDown() and true or false
end

local function OnClick(self, mouseButton, down)
    local cell = self.fsKey
    local PS = Presets()
    if mouseButton == "LeftButton" then
        -- an Alt click (alone or with Ctrl) is blanked in ApplyCell and drops nothing: no press for it
        if AltDown() and not ShiftDown() then return end
        if ShiftDown() then
            if not down then Dial.EditSlot(PS.SlotOf(cell)) end
        elseif IsPressEvent(down) then
            -- an unset cell casts nothing: a press on it is not counted
            if (self.fsAttrKey or "") ~= "" then PS.NotePress(cell) end
        end
    end
end

-- Runs from TotemBar's StyleButton on every seat: builds the face once and seats it at `scale`.
function Dial.StyleCell(button, textHost, scale)
    local s = scale or Scale()
    local size = D.BTN * s
    if button.icon then button.icon:Hide() end
    if button.fsGlyph then button.fsGlyph:Hide() end

    if not button.fsArcs then
        button.fsArcs = {}
        for i = 1, D.RING_ARCS do
            local main = textHost:CreateTexture(nil, "OVERLAY", nil, 1)
            main:SetAllPoints(button)
            main:Hide()
            local core = textHost:CreateTexture(nil, "OVERLAY", nil, 2)
            core:SetAllPoints(button)
            core:Hide()
            button.fsArcs[i] = { main = main, core = core }
        end
        button.fsEmpty = textHost:CreateTexture(nil, "OVERLAY", nil, 1)
        button.fsEmpty:SetAllPoints(button)
        button.fsEmpty:SetTexture(MEDIA .. "totem_dial_empty.tga")
        button.fsEmpty:Hide()
        button.fsDigit = textHost:CreateFontString(nil, "OVERLAY")
        button.fsNext = textHost:CreateTexture(nil, "OVERLAY", nil, 3)
        button.fsNext:SetTexCoord(0.07, 0.93, 0.07, 0.93)
        button.fsNext:Hide()
        button.fsBar = textHost:CreateTexture(nil, "OVERLAY", nil, 2)
        button.fsBar:SetColorTexture(1, 1, 1, 1)
        button.fsTint = Theme.AddCut2Texture(button, Theme.SLICE_CUT2_BUTTON_TEXTURE, { 1, 1, 1, 0 }, "BACKGROUND", -7)
        button.fsDashes = NewDashSet(textHost)
        button.fsBrackets = {}
        for i = 1, 8 do
            local tex = textHost:CreateTexture(nil, "OVERLAY", nil, 5)
            tex:Hide()
            button.fsBrackets[i] = tex
        end
        button.fsRail = NewPlate(button, 7)
        button.fsRaise = NewPlate(button, 8)
        button:HookScript("OnEnter", OnEnter)
        button:HookScript("OnLeave", OnLeave)
        button:HookScript("OnMouseDown", OnMouseDown)
        button:HookScript("OnMouseUp", OnMouseUp)
        button:HookScript("OnHide", OnHide)
        button:HookScript("OnClick", OnClick)
    end

    -- ring centre: 2 design px above the button's centre
    button.fsDigit:ClearAllPoints()
    button.fsDigit:SetPoint("CENTER", button, "CENTER", 0, 2 * s)
    Theme.ApplyMono(button.fsDigit, math.floor(13 * s + 0.5), WHITE)
    button.fsNext:ClearAllPoints()
    button.fsNext:SetPoint("CENTER", button, "CENTER", 0, 2 * s)
    button.fsNext:SetSize(13 * s, 13 * s)
    button.fsBar:ClearAllPoints()
    button.fsBar:SetPoint("BOTTOMLEFT", button, "BOTTOMLEFT", 5 * s, 3 * s)
    button.fsBar:SetPoint("BOTTOMRIGHT", button, "BOTTOMRIGHT", -5 * s, 3 * s)
    button.fsBar:SetHeight(2 * s)
    SeatDashSet(button.fsDashes, button, D.BTN, D.BTN, s)

    -- brackets: two strokes at each corner, standing 2.5 px outside the face
    local o, len, th = D.BRACKET.OFF * s, D.BRACKET.LEN * s, D.BRACKET.THICK * s
    local corners = {
        { "TOPLEFT", -o, o, 1, -1 }, { "TOPRIGHT", o, o, -1, -1 },
        { "BOTTOMLEFT", -o, -o, 1, 1 }, { "BOTTOMRIGHT", o, -o, -1, 1 },
    }
    for i, corner in ipairs(corners) do
        local point, x, y, dx, dy = corner[1], corner[2], corner[3], corner[4], corner[5]
        local h, v = button.fsBrackets[i * 2 - 1], button.fsBrackets[i * 2]
        h:ClearAllPoints()
        h:SetPoint(point, button, point, x, y)
        h:SetSize(len, th)
        v:ClearAllPoints()
        v:SetPoint(point, button, point, x, y)
        v:SetSize(th, len)
    end

    -- plates: the name plate on the rail, the raised one above it
    button.fsRail:ClearAllPoints()
    button.fsRail:SetPoint("BOTTOM", button, "TOP", 0, D.PLATE_RISE * s)
    button.fsRaise:ClearAllPoints()
    button.fsRaise:SetPoint("BOTTOMRIGHT", button, "TOPRIGHT", 2 * s, D.RAISE_RISE * s)
    return size
end

-------------------------------------------------------------------------------
-- Painting a cell
-------------------------------------------------------------------------------

local function PaintArcs(button, st)
    local n = #st.arcs
    for i = 1, D.RING_ARCS do
        local a, item = button.fsArcs[i], st.arcs[i]
        if item then
            local c = item.locked and MUTED or ELEMENT[item.element] or WHITE
            local kind, alpha, core = "t", 0.55, false
            if item.locked then
                kind, alpha = "d", 0.6
            elseif item.state == "done" then
                kind, alpha = "g", 1
            elseif item.state == "next" then
                kind, alpha, core = "k", 0.9, true
            elseif item.state == "wait" then
                alpha = 0.25
            end
            local path = ArcPath(n, i, kind)
            if a.path ~= path then
                a.main:SetTexture(path)
                a.path = path
            end
            Tint(a.main, c, alpha)
            a.main:Show()
            if core then
                local corePath = ArcPath(n, i, "c")
                if a.corePath ~= corePath then
                    a.core:SetTexture(corePath)
                    a.corePath = corePath
                end
                Tint(a.core, WHITE, 0.9)
                a.core:Show()
            else
                a.core:Hide()
            end
        else
            a.main:Hide()
            a.core:Hide()
            a.path, a.corePath = nil, nil
        end
    end
    if n == 0 then
        Tint(button.fsEmpty, MUTED, 0.6)
        button.fsEmpty:Show()
    else
        button.fsEmpty:Hide()
    end
end

local DIM = { 0.051, 0.024, 0.125 }     -- the face colour an unset cell is darkened with

-- Repaints one cell from the rules. Textures, font strings and colours only, so it is legal in combat.
function Paint(button)
    if not (button and button.fsArcs) then return end
    local PS = Presets()
    local st = Dial.StateOf(button.fsKey)
    button.fsState = st
    button.fsColor = st.color
    local s = Scale()
    PaintArcs(button, st)
    local unset = st.preset == nil

    -- the middle: the next totem's icon while a step runs, else the slot's number
    local nextEntry = st.next
    if nextEntry and nextEntry.icon then
        button.fsNext:SetTexture(nextEntry.icon)
        button.fsNext:Show()
        button.fsDigit:Hide()
    else
        button.fsNext:Hide()
        button.fsDigit:SetText(st.digit)
        local c = st.empty and MUTED or WHITE
        button.fsDigit:SetTextColor(c[1], c[2], c[3], 1)
        button.fsDigit:Show()
    end

    -- the border, the glow, the underline and the fill: the outline colour, or muted and dashed when the slot is unset
    local hover = button.fsHover and true or false
    local pressed = hover and button.fsPressed and true or false
    local skin = button.fsSkin
    local ring = skin and skin.border and skin.border.ring
    local glow = skin and skin.glow
    local edge = unset and MUTED or st.color
    if unset then
        if ring then ring:SetVertexColor(MUTED[1], MUTED[2], MUTED[3], 0) end
        if glow then glow:SetVertexColor(MUTED[1], MUTED[2], MUTED[3], 0) end
        PaintDashSet(button.fsDashes, MUTED, hover and 1 or 0.6, true)
        Tint(button.fsBar, MUTED, 0.5)
        if hover then
            Tint(button.fsTint, MUTED, pressed and 0.32 or 0.16)
        else
            Tint(button.fsTint, DIM, 0.35)
        end
    else
        if ring then ring:SetVertexColor(edge[1], edge[2], edge[3], 1) end
        if glow then glow:SetVertexColor(edge[1], edge[2], edge[3], hover and 0.6 or 0.35) end
        PaintDashSet(button.fsDashes, MUTED, 0, false)
        Tint(button.fsBar, edge, 0.9)
        Tint(button.fsTint, edge, pressed and 0.32 or (hover and 0.16 or 0))
    end
    for _, tex in ipairs(button.fsBrackets) do
        tex:SetColorTexture(CYAN[1], CYAN[2], CYAN[3], 1)
        if nextEntry then tex:Show() else tex:Hide() end
    end

    -- the plates: the name in the outline colour, and while a step runs the count
    if PS.Setting(PS.SETTINGS.plate) then
        SetPlate(button.fsRail, { text = st.name, color = edge, textColor = edge, height = D.PLATE_H,
            edgeAlpha = unset and 0.5 or 0.9 }, s)
    else
        button.fsRail:Hide()
    end
    if st.stepping then
        local squares = {}
        for _, item in ipairs(st.arcs) do
            if not item.locked then
                squares[#squares + 1] = { ELEMENT[item.element] or WHITE, item.state }
            end
        end
        SetPlate(button.fsRaise, { text = st.k .. "/" .. st.total, color = edge, textColor = WHITE, wide = true,
            height = D.RAISE_H, edgeAlpha = 0.85, squares = squares }, s)
    else
        button.fsRaise:Hide()
    end
end
Dial.Paint = Paint

-------------------------------------------------------------------------------
-- Tooltips
-------------------------------------------------------------------------------

local function Line(tip, text, c, wrap)
    tip:AddLine(text, c[1], c[2], c[3], wrap and true or false)
end

local GOLD = { 1, 0.82, 0 }

function Dial.Tooltip(button)
    local tip = GameTooltip
    if not tip then return end
    local PS = Presets()
    if FS.FrameHelpers and FS.FrameHelpers.AnchorTooltip then FS.FrameHelpers.AnchorTooltip(button) end
    local st = Dial.StateOf(button.fsKey)
    local idle = PS.P.STEP_IDLE
    if not st.preset then
        Line(tip, "PRESET " .. st.slot .. ": UNSET", MUTED)
        Line(tip, "Empty. Shift click to make it from your totem buttons.", MUTED, true)
    else
        Line(tip, "PRESET " .. st.slot .. ": " .. st.name, st.color)
        Dial.PresetLines(tip, st.preset)
        Line(tip, "Click: drop the next totem. Shift click: edit. Always ready, even in combat.", GOLD, true)
        Line(tip, "Starts over after combat ends or a " .. idle .. " s pause.", CYAN, true)
    end
    tip:Show()
end

-- The preset's totems as numbered lines in drop order, then the elements it leaves out, muted.
function Dial.PresetLines(tip, preset)
    local PS = Presets()
    local entries = PS.Entries(preset)
    local used = {}
    for i, entry in ipairs(entries) do
        used[entry.element] = true
        local text = i .. " " .. Swatch(ELEMENT[entry.element] or WHITE) .. entry.name
        if entry.known then
            Line(tip, text, WHITE)
        else
            Line(tip, text .. " (level " .. entry.level .. ")", MUTED)
        end
    end
    for _, element in ipairs(PS.P.ELEMENTS) do
        if not used[element] then
            Line(tip, Swatch(ELEMENT[element]) .. ELEMENT_NAME[element] .. ": left out", MUTED)
        end
    end
end

-------------------------------------------------------------------------------
-- The cell's secure attributes (out of combat, from the totem tab's Sync)
-------------------------------------------------------------------------------

-- Every modifier click that edits instead of dropping: shift, alt, and each combination that holds one of them with
-- another modifier (a combo with no attribute of its own falls back to the plain type1 and would drop a totem).
-- Blizzard's SecureTemplates builds the prefix only in the order alt-ctrl-shift-.
local EDIT_CLICKS = { "shift-type1", "alt-type1", "alt-shift-type1", "alt-ctrl-type1", "alt-ctrl-shift-type1",
    "ctrl-shift-type1" }

local function ClearAttributes(button)
    for _, name in ipairs({ "type1", "macrotext1", "type2", "ctrl-type1" }) do
        button:SetAttribute(name, nil)
    end
    for _, name in ipairs(EDIT_CLICKS) do button:SetAttribute(name, nil) end
end

function Dial.ApplyCell(button, def)
    local PS = Presets()
    button.fsKey = def.key
    local text = PS.StepText(PS.CellPreset(def.key))
    local key = text or ""
    if button.fsAttrKey ~= key then
        ClearAttributes(button)
        if text then
            button:SetAttribute("type1", "macro")
            button:SetAttribute("macrotext1", text)
        end
        -- Shift and Alt clicks (alone or with another modifier) are ours (edit): an empty type means they never drop
        for _, name in ipairs(EDIT_CLICKS) do button:SetAttribute(name, "") end
        button.fsAttrKey = key
    end
    local c = PS.ColorRgb(PS.SlotOf(def.key))
    if c then button.fsColor = { c[1], c[2], c[3] } end
end

-------------------------------------------------------------------------------
-- The editor
-------------------------------------------------------------------------------

local card, chooser

local function Mono(fs, size, c)
    Theme.ApplyMono(fs, math.floor(size * Scale() + 0.5), c or WHITE)
end

-- Pixels. The editor draws on whole physical pixels: sizes and offsets are rounded to the screen's pixels, boxes that
-- centre something are an EVEN number of pixels (so the centre is a pixel edge), and lines and glyphs are textures one
-- pixel thick that snap to the pixel grid. Es is the physical pixels in one UI unit (FrameHelpers.PixelsPerUnit: the pixel
-- factor over the effective scale, NOT the effective scale itself).
local function Es(frame)
    return FS.FrameHelpers.PixelsPerUnit(frame)
end

local function PxRound(frame, v)
    local es = Es(frame)
    return math.floor(v * es + 0.5) / es
end

local function PxThick(frame, v)
    local es = Es(frame)
    return math.max(1, math.floor(v * es + 0.5)) / es
end

local function PxEven(frame, v)
    local es = Es(frame)
    local n = math.max(2, math.ceil(v * es - 1e-6))
    if n % 2 == 1 then n = n + 1 end
    return n / es
end

local function Snap(tex)
    if tex and tex.SetSnapToPixelGrid then
        pcall(tex.SetSnapToPixelGrid, tex, true)
        if tex.SetTexelSnappingBias then pcall(tex.SetTexelSnappingBias, tex, 0) end
    end
end

local function SnapAll(list)
    for i = 1, #list do Snap(list[i]) end
end

local function Edges(frame, layer, sub)
    local edges = NewEdges(frame, layer, sub)
    SnapAll(edges)
    return edges
end

local function Mix3(a, b, t)
    return { a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t }
end

local FILL = { 0.051, 0.024, 0.125 }

-- A button's look from its state. Normal comes from b.fsLook (ring colour, text colour, fill, edge alpha, a fill mix
-- toward the ring); hover brightens the fill toward the ring (the config window's hover, 0.16) and takes the ring to full
-- alpha, pressed goes further (0.32), disabled is the frame at alpha 0.4 and ignores the mouse. Textures and colours only.
local function PaintButton(b)
    local look = b.fsLook
    if not look then return end
    local live = not b.fsDisabled
    local hover, pressed = live and b.fsHover, live and b.fsPressed
    local mix = (pressed and 0.32) or (hover and 0.16) or look.mix or 0
    local f = Mix3(look.fill or FILL, look.ring, mix)
    b.fill:SetColorTexture(f[1], f[2], f[3], look.fillA or 0.8)
    SetEdges(b.edges, look.ring, (hover or pressed) and 1 or (look.edgeA or 0.8))
    local tc = (hover or pressed) and WHITE or look.text
    b.text:SetTextColor(tc[1], tc[2], tc[3], 1)
    if b.glyph then
        for i = 1, #b.glyph do b.glyph[i]:SetColorTexture(tc[1], tc[2], tc[3], 1) end
    end
    b:SetAlpha(b.fsDisabled and 0.4 or 1)
    if b.fsAfter then b.fsAfter(b) end
end

local function SetDisabled(b, off)
    off = off and true or false
    b.fsDisabled = off
    if b.SetEnabled then pcall(b.SetEnabled, b, not off) end
    PaintButton(b)
end

local function NewButton(parent, w, h)
    local b = CreateFrame("Button", nil, parent)
    b:SetSize(w, h)
    b.fill = b:CreateTexture(nil, "BACKGROUND")
    b.fill:SetAllPoints(b)
    b.fill:SetColorTexture(FILL[1], FILL[2], FILL[3], 0.8)
    b.edges = Edges(b, "BORDER", 0)
    b.text = b:CreateFontString(nil, "OVERLAY")
    b.text:SetPoint("CENTER", b, "CENTER", 0, 0)
    b:RegisterForClicks("LeftButtonUp")
    b:SetScript("OnEnter", function(self) self.fsHover = true; PaintButton(self) end)
    b:SetScript("OnLeave", function(self) self.fsHover, self.fsPressed = false, false; PaintButton(self) end)
    b:SetScript("OnMouseDown", function(self) self.fsPressed = true; PaintButton(self) end)
    b:SetScript("OnMouseUp", function(self) self.fsPressed = false; PaintButton(self) end)
    b:SetScript("OnHide", function(self) self.fsHover, self.fsPressed = false, false end)
    return b
end

-- Styles a text button: `c` is its ring colour (MUTED keeps the label muted too), `o` { mix, edgeA, fill, fillA }.
local function StyleButton(b, c, text, size, o)
    o = o or {}
    SeatEdges(b.edges, b, PxThick(b, math.max(1, Scale())))
    local tc = c == MUTED and MUTED or WHITE
    b.fsTextColor = tc
    b.fsLook = { ring = c, text = tc, mix = o.mix, edgeA = o.edgeA, fill = o.fill, fillA = o.fillA }
    Mono(b.text, size or 9, tc)
    b.text:SetText(text)
    PaintButton(b)
end

-- A glyph drawn as whole-pixel squares on button `b`: `cells` are { x, y } pixels from the glyph's top left, w and h its
-- size in pixels. The margins to the button are equal on both sides when the button's size and the glyph's have the same
-- parity (the buttons are even, the glyphs are even).
local function SeatGlyph(b, cells, w, h)
    local px = 1 / Es(b)
    local es = Es(b)
    local bw, bh = math.floor(b:GetWidth() * es + 0.5), math.floor(b:GetHeight() * es + 0.5)
    local mx, my = math.floor((bw - w) / 2), math.floor((bh - h) / 2)
    b.glyph = b.glyph or {}
    for i, cell in ipairs(cells) do
        local t = b.glyph[i]
        if not t then
            t = b:CreateTexture(nil, "OVERLAY")
            Snap(t)
            b.glyph[i] = t
        end
        t:ClearAllPoints()
        t:SetSize(px, px)
        t:SetPoint("TOPLEFT", b, "TOPLEFT", (mx + cell[1]) * px, -(my + cell[2]) * px)
        t:Show()
    end
    for i = #cells + 1, #b.glyph do b.glyph[i]:Hide() end
end

-- A chevron h pixels tall and 2h wide: up (the point at the top) or down.
local function ChevronCells(h, up)
    local cells = {}
    for r = 0, h - 1 do
        local y = up and r or (h - 1 - r)
        cells[#cells + 1] = { h - 1 - r, y }
        cells[#cells + 1] = { h + r, y }
    end
    return cells
end

-- A pick cell (row tile, chooser tile): a ring of edges in the element's colour that shows on hover and is full while
-- pressed; disabled dims the cell and shows no ring. Textures and colours only.
local function PaintTile(t)
    local a = 0
    if not t.fsDisabled then a = t.fsPressed and 1 or (t.fsHover and 0.9 or 0) end
    SetEdges(t.hl, t.fsRing or WHITE, a)
    t:SetAlpha(t.fsDisabled and 0.4 or 1)
    if t.fsAfter then t.fsAfter(t) end
end

-- Disables or enables a pick cell: dimmed, no ring, and the engine drops its clicks.
local function SetTileDisabled(t, off)
    off = off and true or false
    t.fsDisabled = off
    if t.SetEnabled then pcall(t.SetEnabled, t, not off) end
    PaintTile(t)
end

local function NewTileHover(t)
    t.hl = Edges(t, "OVERLAY", 2)
    PaintTile(t)
    t:SetScript("OnMouseDown", function(self) self.fsPressed = true; PaintTile(self) end)
    t:SetScript("OnMouseUp", function(self) self.fsPressed = false; PaintTile(self) end)
    t:SetScript("OnHide", function(self) self.fsHover, self.fsPressed = false, false end)
end

-- A dashed box on a frame, drawn in whole pixels (the mockup's dbox: 2 pixels on, 2 off, one pixel thick): a pool of
-- snapped textures on `host`, seated to the frame by SeatDashBox, which creates them as the pixel size needs runs.
local function NewDashTexture(box)
    local t = box.host:CreateTexture(nil, "OVERLAY", nil, 2)
    Snap(t)
    t:Hide()
    box[#box + 1] = t
    return t
end

local function NewDashBox(host)
    return { host = host }
end

local function SeatDashBox(box, frame)
    local es = Es(frame)
    local pw, ph = math.floor(frame:GetWidth() * es + 0.5), math.floor(frame:GetHeight() * es + 0.5)
    local px = 1 / es
    local n = 0
    local function put(x, y, w, h)
        n = n + 1
        local t = box[n] or NewDashTexture(box)
        t:ClearAllPoints()
        t:SetPoint("TOPLEFT", frame, "TOPLEFT", x * px, -y * px)
        t:SetSize(w * px, h * px)
    end
    -- runs of "on" pixels along one side: pixel k is on when floor(k / 2) is even
    local function runs(from, to, place)
        local start
        for k = from, to + 1 do
            local on = k <= to and math.floor(k / 2) % 2 == 0
            if on and not start then start = k end
            if not on and start then place(start, k - start); start = nil end
        end
    end
    runs(0, pw - 1, function(x, len) put(x, 0, len, 1); put(x, ph - 1, len, 1) end)
    runs(1, ph - 2, function(y, len) put(0, y, 1, len); put(pw - 1, y, 1, len) end)
    box.n = n
    for i = n + 1, #box do box[i]:Hide() end
end

-- Colours the dashes and shows the seated ones (or hides them all). The pool only grows while seating, and every seat is
-- followed by a paint, so a new dash takes its colour here.
local function PaintDashBox(box, c, a, show)
    for i = 1, #box do
        box[i]:SetColorTexture(c[1], c[2], c[3], a)
        box[i]:SetShown(show and i <= (box.n or 0))
    end
end

local function PaintName()
    local n = card and card.name
    if not n then return end
    local live = not n.fsDisabled
    SetEdges(card.nameEdges, CYAN, n.fsFocus and 1 or ((live and n.fsHover) and 0.75 or 0.4))
    local f = Mix3({ 0.039, 0.016, 0.086 }, CYAN, (live and n.fsHover and not n.fsFocus) and 0.08 or 0)
    n.fill:SetColorTexture(f[1], f[2], f[3], 1)
    n:SetAlpha(n.fsDisabled and 0.4 or 1)
end

local function CloseChooser()
    if chooser and chooser:IsShown() then chooser:Hide() end
end

-- Dims and disables the chooser's tiles while the presets cannot be edited (the refusal can begin with the chooser open).
local function LockChooser(locked)
    if not (chooser and chooser:IsShown()) then return end
    for _, tile in ipairs(chooser.tiles) do
        if tile:IsShown() then SetTileDisabled(tile, locked) end
    end
end

function Dial.CloseEditor()
    CloseChooser()
    if card and card:IsShown() then card:Hide() end
end

-- The elements as the rows list them: the preset's own, in drop order, then the ones it leaves out (an unset slot lists
-- all four in the default order).
local function ElementOrder(preset)
    local out, used = {}, {}
    for _, element in ipairs(preset and preset.order or Presets().P.DEFAULT_ORDER) do
        out[#out + 1] = element
        used[element] = true
    end
    for _, element in ipairs(Presets().P.ELEMENTS) do
        if not used[element] then out[#out + 1] = element end
    end
    return out
end

local function Refuse(why)
    if why and UIErrorsFrame and UIErrorsFrame.AddMessage then UIErrorsFrame:AddMessage(why, 1, 0.3, 0.3) end
end

-- the list of known totems for a row: tiles for each, and "left out"
local function OpenChooser(row)
    local PS = Presets()
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    local why = PS.Refusal()
    if why then return Refuse(why) end
    if not chooser then
        chooser = CreateFrame("Frame", "FSTotemChooser", UIParent)
        chooser:SetFrameStrata("DIALOG")
        chooser:SetFrameLevel(card:GetFrameLevel() + 10)
        chooser:EnableMouse(true)
        chooser.fill = chooser:CreateTexture(nil, "BACKGROUND")
        chooser.fill:SetAllPoints(chooser)
        chooser.fill:SetColorTexture(0.051, 0.024, 0.125, 0.97)
        chooser.edges = Edges(chooser, "BORDER", 0)
        chooser.tiles = {}
        chooser:Hide()
    end
    local s = Scale()
    local element, index = row.fsElement, card.fsIndex
    local tb = Totems()
    local list = tb.KnownList(element)
    local items = {}
    for _, item in ipairs(list) do
        local base = PS.BaseOf(element, item)
        if base then items[#items + 1] = { base = base, id = item.id, icon = item.icon, name = item.name } end
    end
    items[#items + 1] = { leave = true }
    local size = PxEven(chooser, D.CHOOSER_TILE * s)
    local pad = PxRound(chooser, 3 * s)
    chooser:SetSize(#items * size + (#items + 1) * pad, size + 2 * pad)
    local thick = PxThick(chooser, math.max(1, s))
    SeatEdges(chooser.edges, chooser, thick)
    SetEdges(chooser.edges, ELEMENT[element] or VIOLET, 0.85)
    local preset = PS.Get(index)
    local current = preset and preset.picks[element]
    for i = 1, math.max(#items, #chooser.tiles) do
        local tile = chooser.tiles[i]
        if not tile then
            tile = CreateFrame("Button", nil, chooser)
            tile:RegisterForClicks("LeftButtonUp")
            tile.icon = tile:CreateTexture(nil, "ARTWORK")
            tile.icon:SetAllPoints(tile)
            tile.icon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
            tile.mark = tile:CreateTexture(nil, "OVERLAY")
            tile.text = tile:CreateFontString(nil, "OVERLAY")
            tile.text:SetPoint("CENTER", tile, "CENTER", 0, 0)
            NewTileHover(tile)
            tile:SetScript("OnClick", function(self)
                local why = PS.Refusal()
                if why then return Refuse(why) end
                local edit, reason = PS.SetTotem(card.fsIndex, self.fsElement, self.fsBase)
                if edit == false then return Refuse(reason) end
                CloseChooser()
                Dial.RefreshCard()
            end)
            tile:SetScript("OnEnter", function(self)
                self.fsHover = true
                PaintTile(self)
                if self.fsSpell and GameTooltip and GameTooltip.SetSpellByID then
                    GameTooltip:SetOwner(self, "ANCHOR_TOP")
                    GameTooltip:SetSpellByID(self.fsSpell)
                    GameTooltip:Show()
                elseif GameTooltip then
                    GameTooltip:SetOwner(self, "ANCHOR_TOP")
                    GameTooltip:AddLine("Leave this element out", MUTED[1], MUTED[2], MUTED[3])
                    GameTooltip:Show()
                end
            end)
            tile:SetScript("OnLeave", function(self)
                self.fsHover, self.fsPressed = false, false
                PaintTile(self)
                if GameTooltip then GameTooltip:Hide() end
            end)
            chooser.tiles[i] = tile
        end
        local item = items[i]
        if item then
            tile:ClearAllPoints()
            tile:SetPoint("LEFT", chooser, "LEFT", pad + (i - 1) * (size + pad), 0)
            tile:SetSize(size, size)
            tile.fsElement, tile.fsBase, tile.fsSpell = element, item.base, item.id
            tile.fsRing = ELEMENT[element] or WHITE
            SeatEdges(tile.hl, tile, thick)
            SetTileDisabled(tile, false)
            if item.leave then
                tile.icon:SetColorTexture(0.04, 0.02, 0.09, 0.9)
                Mono(tile.text, 11, MUTED)
                tile.text:SetText("--")
                tile.text:Show()
            else
                tile.icon:SetTexture(item.icon)
                tile.text:Hide()
            end
            tile.mark:ClearAllPoints()
            tile.mark:SetPoint("BOTTOMLEFT", tile, "BOTTOMLEFT", PxRound(tile, 2 * s), PxRound(tile, 1 * s))
            tile.mark:SetPoint("BOTTOMRIGHT", tile, "BOTTOMRIGHT", -PxRound(tile, 2 * s), PxRound(tile, 1 * s))
            tile.mark:SetHeight(PxThick(tile, 2 * s))
            local c = ELEMENT[element] or WHITE
            tile.mark:SetColorTexture(c[1], c[2], c[3], 1)
            tile.mark:SetShown((item.leave and current == nil) or (not item.leave and current == item.base))
            tile:Show()
        elseif tile then
            tile:Hide()
        end
    end
    chooser:ClearAllPoints()
    chooser:SetPoint("TOPRIGHT", row, "TOPLEFT", -PxRound(chooser, 4 * s), 0)
    chooser:Show()
end

-- An outline swatch: a tinted square with a ring in its colour and a dot (the mockup's states: quiet, hover, pressed, and
-- selected with a white outer ring, an inner ring in its colour and a bigger dot). Disabled is the frame at alpha 0.4.
local function PaintSwatch(sw)
    local c = sw.fsRgb
    if not c then return end
    local live = not sw.fsDisabled
    local hover, pressed = live and sw.fsHover, live and sw.fsPressed
    local selected = sw.fsSelected
    local f = Mix3(FILL, c, pressed and 0.5 or ((hover or selected) and 0.35 or 0.22))
    sw.fill:SetColorTexture(f[1], f[2], f[3], 1)
    local bright = hover or pressed
    if selected then
        SetEdges(sw.edges, WHITE, 1)
        SetEdges(sw.inner, c, 1)
        for i = 1, #sw.inner do sw.inner[i]:Show() end
    else
        SetEdges(sw.edges, c, bright and 1 or 0.6)
        for i = 1, #sw.inner do sw.inner[i]:Hide() end
    end
    sw.dot:SetColorTexture(c[1], c[2], c[3], (selected or bright) and 1 or 0.9)
    local d = selected and sw.fsDotBig or sw.fsDotSmall
    if d then sw.dot:SetSize(d, d) end
    sw:SetAlpha(sw.fsDisabled and 0.4 or 1)
end

local function SetSwatchDisabled(sw, off)
    sw.fsDisabled = off and true or false
    if sw.SetEnabled then pcall(sw.SetEnabled, sw, not off) end
    PaintSwatch(sw)
end

local function BuildSwatch(parent, index)
    local PS = Presets()
    local def = PS.P.COLORS[index]
    local sw = CreateFrame("Button", nil, parent)
    sw:RegisterForClicks("LeftButtonUp")
    sw.fsColor = index
    sw.fsRgb = def.rgb
    sw.fsName = string.upper(def.key)
    sw.fill = sw:CreateTexture(nil, "BACKGROUND")
    sw.fill:SetAllPoints(sw)
    sw.edges = Edges(sw, "BORDER", 1)
    sw.inner = Edges(sw, "BORDER", 2)
    sw.dot = sw:CreateTexture(nil, "ARTWORK")
    Snap(sw.fill)
    Snap(sw.dot)
    sw:SetScript("OnEnter", function(self)
        self.fsHover = true
        PaintSwatch(self)
        if GameTooltip then
            GameTooltip:SetOwner(self, "ANCHOR_TOP")
            GameTooltip:AddLine(self.fsName, MUTED[1], MUTED[2], MUTED[3])
            GameTooltip:Show()
            self.fsTip = true
        end
    end)
    sw:SetScript("OnLeave", function(self)
        self.fsHover, self.fsPressed = false, false
        PaintSwatch(self)
        if GameTooltip then GameTooltip:Hide() end
        self.fsTip = false
    end)
    sw:SetScript("OnMouseDown", function(self) self.fsPressed = true; PaintSwatch(self) end)
    sw:SetScript("OnMouseUp", function(self) self.fsPressed = false; PaintSwatch(self) end)
    sw:SetScript("OnHide", function(self)
        self.fsHover, self.fsPressed = false, false
        PaintSwatch(self)
        if self.fsTip and GameTooltip then GameTooltip:Hide() end
        self.fsTip = false
    end)
    sw:SetScript("OnClick", function(self)
        local why = PS.Refusal()
        if why then return Refuse(why) end
        local ok, reason = PS.SetColor(card.fsIndex, self.fsColor)
        if ok == false then Refuse(reason) end
        Dial.RefreshCard()
    end)
    return sw
end

local function SeatCard()
    local s = Scale()
    local C = D.CARD
    local function u(v) return PxRound(card, v * s) end
    local function even(v) return PxEven(card, v * s) end
    local cardW = PxEven(card, C.W * s)
    local thick = PxThick(card, math.max(1, s))
    card:SetSize(cardW, u(C.TOP + C.ROWS * C.ROW + C.FOOT))
    SeatEdges(card.edges, card, thick)
    SetEdges(card.edges, VIOLET, 0.85)
    card.title:ClearAllPoints()
    card.title:SetPoint("TOPLEFT", card, "TOPLEFT", u(8), -u(4))
    Mono(card.title, 10, MUTED)
    card.name:ClearAllPoints()
    card.name:SetPoint("TOPLEFT", card, "TOPLEFT", u(8), -u(C.NAME_Y))
    card.name:SetSize(cardW - 2 * u(8), even(18))
    Mono(card.name, 12, WHITE)
    card.nameEdges = card.nameEdges or Edges(card.name, "BORDER", 0)
    SeatEdges(card.nameEdges, card.name, thick)
    card.outline:ClearAllPoints()
    card.outline:SetPoint("TOPLEFT", card, "TOPLEFT", u(8), -u(C.OUTLINE_Y))
    Mono(card.outline, 9, MUTED)
    card.outline:SetText("OUTLINE")
    -- the swatches: an even square each on one pitch, the dot an even square centred in it
    local pitch, size = u(C.PITCH), even(C.SWATCH)
    for i, sw in ipairs(card.swatches) do
        sw:ClearAllPoints()
        sw:SetPoint("TOPLEFT", card, "TOPLEFT", u(8) + (i - 1) * pitch, -u(C.SWATCH_Y))
        sw:SetSize(size, size)
        SeatEdges(sw.edges, sw, thick)
        SeatEdges(sw.inner, sw, thick, thick)
        sw.dot:ClearAllPoints()
        sw.dot:SetPoint("CENTER", sw, "CENTER", 0, 0)
        sw.fsDotSmall, sw.fsDotBig = even(6), even(8)
        PaintSwatch(sw)
    end
    card.label:ClearAllPoints()
    card.label:SetPoint("TOPLEFT", card, "TOPLEFT", u(8), -u(C.LABEL_Y))
    Mono(card.label, 9, MUTED)
    card.label:SetText("DROP ORDER")
    for i, row in ipairs(card.rows) do
        row:ClearAllPoints()
        row:SetPoint("TOPLEFT", card, "TOPLEFT", u(8), -u(C.TOP + (i - 1) * C.ROW))
        row:SetSize(cardW - 2 * u(8), even(C.ROW - 4))
        row.num:ClearAllPoints()
        row.num:SetPoint("LEFT", row, "LEFT", u(6), 0)
        Mono(row.num, 11, WHITE)
        row.bar:ClearAllPoints()
        row.bar:SetPoint("LEFT", row, "LEFT", u(19), 0)
        row.bar:SetSize(u(3), even(14))
        row.tile:ClearAllPoints()
        row.tile:SetPoint("LEFT", row, "LEFT", u(26), 0)
        row.tile:SetSize(even(22), even(22))
        SeatEdges(row.tile.hl, row.tile, thick)
        SeatDashBox(row.tile.dashes, row.tile)
        row.label:ClearAllPoints()
        row.label:SetPoint("LEFT", row, "LEFT", u(52), 0)
        Mono(row.label, 10, WHITE)
        local aw, ah = even(12), even(14)
        row.up:ClearAllPoints()
        row.up:SetPoint("RIGHT", row, "RIGHT", -u(22), 0)
        row.up:SetSize(aw, ah)
        row.down:ClearAllPoints()
        row.down:SetPoint("RIGHT", row, "RIGHT", -u(6), 0)
        row.down:SetSize(aw, ah)
        -- the arrows are chevrons h pixels tall and 2h wide, h even, with room left either side
        local h = math.max(2, 2 * math.floor((math.floor(aw * Es(row.up) + 0.5) - 4) / 4))
        for _, pair in ipairs({ { row.up, true }, { row.down, false } }) do
            SeatEdges(pair[1].edges, pair[1], thick)
            SeatGlyph(pair[1], ChevronCells(h, pair[2]), 2 * h, h)
        end
        SeatEdges(row.edges, row, thick)
    end
    -- CLEAR is one button across the card (its label is the same width for CLEAR and SURE?: nothing jumps)
    card.clear:ClearAllPoints()
    card.clear:SetPoint("BOTTOMLEFT", card, "BOTTOMLEFT", u(8), u(7))
    card.clear:SetSize(cardW - 2 * u(8), even(18))
end

-- A row's look: the fill tints toward the violet ring on hover (0.16) and press (0.32), the ring goes to full alpha with the
-- mouse on the row or on one of its arrows, and the icon box ring (the element's colour) rises from 0.35 to 0.9. Disabled
-- dims every piece to alpha 0.4 and shows no hover. Textures and colours only.
local function PaintRow(row)
    local live = not row.fsDisabled
    local hover, pressed = live and row.fsHover, live and row.fsPressed
    local lit = live and (hover or pressed or (not row.up.fsDisabled and row.up.fsHover) or (not row.down.fsDisabled and row.down.fsHover))
    local f = Mix3(FILL, VIOLET, pressed and 0.32 or (hover and 0.16 or 0))
    row.fill:SetColorTexture(f[1], f[2], f[3], 0.8)
    local k = row.fsDisabled and 0.4 or 1
    SetEdges(row.edges, VIOLET, (lit and 1 or 0.35) * k)
    local boxA = row.fsSet and ((hover or pressed) and 0.9 or 0.35) or 0
    SetEdges(row.tile.hl, row.tile.fsRing or WHITE, boxA * k)
    -- a left out row has a dashed muted box in place of the ring
    PaintDashBox(row.tile.dashes, MUTED, 0.6, not row.fsSet)
    for _, piece in ipairs({ row.fill, row.num, row.bar, row.label, row.tile }) do piece:SetAlpha(k) end
end

local function SetRowDisabled(row, off)
    row.fsDisabled = off and true or false
    if row.SetEnabled then pcall(row.SetEnabled, row, not off) end
    PaintRow(row)
end

-- One drop order row: a single button for its whole width (bar, number, icon, name), with the two arrows small buttons on top.
local function BuildRow(parent)
    local row = CreateFrame("Button", nil, parent)
    row:RegisterForClicks("LeftButtonUp")
    row.fill = row:CreateTexture(nil, "BACKGROUND")
    row.fill:SetAllPoints(row)
    row.edges = Edges(row, "BORDER", 0)
    row.num = row:CreateFontString(nil, "OVERLAY")
    row.bar = row:CreateTexture(nil, "ARTWORK")
    row.tile = CreateFrame("Frame", nil, row)           -- the icon box: it draws, the row takes the mouse
    row.tile.icon = row.tile:CreateTexture(nil, "ARTWORK")
    row.tile.icon:SetAllPoints(row.tile)
    row.tile.icon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
    row.tile.hl = Edges(row.tile, "OVERLAY", 2)
    row.tile.dashes = NewDashBox(row.tile)
    row.tile.text = row.tile:CreateFontString(nil, "OVERLAY")
    row.tile.text:SetPoint("CENTER", row.tile, "CENTER", 0, 0)
    row.label = row:CreateFontString(nil, "OVERLAY")
    row.up = NewButton(row, 12, 14)
    row.down = NewButton(row, 12, 14)
    row.up.fsLook = { ring = MUTED, text = MUTED }
    row.down.fsLook = { ring = MUTED, text = MUTED }
    -- hovering an arrow lights the row's edge
    local function lit() PaintRow(row) end
    row.up.fsAfter, row.down.fsAfter = lit, lit
    PaintButton(row.up)
    PaintButton(row.down)
    row:SetScript("OnEnter", function(self) self.fsHover = true; PaintRow(self) end)
    row:SetScript("OnLeave", function(self) self.fsHover, self.fsPressed = false, false; PaintRow(self) end)
    row:SetScript("OnMouseDown", function(self) self.fsPressed = true; PaintRow(self) end)
    row:SetScript("OnMouseUp", function(self) self.fsPressed = false; PaintRow(self) end)
    row:SetScript("OnHide", function(self) self.fsHover, self.fsPressed = false, false; PaintRow(self) end)
    row:SetScript("OnClick", function(self) OpenChooser(self) end)
    row.up:SetScript("OnClick", function()
        local ok, why = Presets().Move(card.fsIndex, row.fsElement, -1)
        if ok == false then Refuse(why) end
        Dial.RefreshCard()
    end)
    row.down:SetScript("OnClick", function()
        local ok, why = Presets().Move(card.fsIndex, row.fsElement, 1)
        if ok == false then Refuse(why) end
        Dial.RefreshCard()
    end)
    return row
end

local function Commit()
    local PS = Presets()
    if not card or not card.fsIndex then return end
    local text = card.name:GetText()
    local preset = PS.Get(card.fsIndex)
    local cleaned = PS.CleanName(text)
    if cleaned ~= "" and (not preset or cleaned ~= preset.name) then
        local ok, why = PS.Rename(card.fsIndex, text)
        if ok == false then Refuse(why) end
    end
end

local function BuildCard()
    if card then return card end
    local PS = Presets()
    card = CreateFrame("Frame", "FSTotemEditor", UIParent)
    card:SetFrameStrata("DIALOG")
    card:EnableMouse(true)
    card.fill = card:CreateTexture(nil, "BACKGROUND")
    card.fill:SetAllPoints(card)
    card.fill:SetColorTexture(0.051, 0.024, 0.125, 0.97)
    card.edges = Edges(card, "BORDER", 0)
    card.title = card:CreateFontString(nil, "OVERLAY")
    card.close = FS.ButtonSkins.NewCloseButton(card, function() Dial.CloseEditor() end) -- the shared STUwave X, seats itself
    card.name = CreateFrame("EditBox", nil, card)
    card.name:SetAutoFocus(false)
    card.name:SetMaxLetters(PS.P.NAME_MAX)
    card.name:SetTextInsets(5, 5, 0, 0)
    card.name.fill = card.name:CreateTexture(nil, "BACKGROUND")
    card.name.fill:SetAllPoints(card.name)
    card.name.fill:SetColorTexture(0.039, 0.016, 0.086, 1)
    card.name:SetScript("OnEnterPressed", function(self)
        Commit()
        self:ClearFocus()
    end)
    card.name:SetScript("OnEscapePressed", function(self)
        Dial.RefreshCard()
        self:ClearFocus()
    end)
    card.name:SetScript("OnEditFocusGained", function(self)
        if self.fsFocus then return end
        self.fsFocus = true
        PaintName()
    end)
    card.name:SetScript("OnEditFocusLost", function(self)
        self.fsFocus = false
        PaintName()
        Commit()
    end)
    card.name:SetScript("OnEnter", function(self) self.fsHover = true; PaintName() end)
    card.name:SetScript("OnLeave", function(self) self.fsHover = false; PaintName() end)
    card.name:SetScript("OnHide", function(self) self.fsHover = false; PaintName() end)
    card.label = card:CreateFontString(nil, "OVERLAY")
    card.rows = {}
    card.outline = card:CreateFontString(nil, "OVERLAY")
    card.swatches = {}
    for i = 1, #PS.P.COLORS do card.swatches[i] = BuildSwatch(card, i) end
    for i = 1, D.CARD.ROWS do card.rows[i] = BuildRow(card) end
    card.clear = NewButton(card, 58, 18)
    card.clear:SetScript("OnClick", function(self)
        local PS = Presets()
        local why = PS.Refusal()
        if why then return Refuse(why) end
        if PS.IsEmpty(card.fsIndex) then return end
        local now = GetTime and GetTime() or 0
        if card.fsConfirm and now - card.fsConfirm < D.CONFIRM then
            card.fsConfirm = nil
            local ok, reason = PS.Clear(card.fsIndex)
            if ok == false then Refuse(reason) end
            Dial.RefreshCard()
        else
            card.fsConfirm = now
            StyleButton(self, PINK, "SURE?", 9, { mix = 0.22, edgeA = 1 })
        end
    end)
    card:SetScript("OnHide", function(self)
        CloseChooser()
        for _, sw in ipairs(self.swatches) do
            if sw.fsTip and GameTooltip then GameTooltip:Hide() end
            sw.fsTip = false
        end
        self.fsConfirm = nil
        if self.name.ClearFocus then self.name:ClearFocus() end
    end)
    SeatCard()
    if type(_G.UISpecialFrames) == "table" then table.insert(_G.UISpecialFrames, "FSTotemEditor") end
    card:Hide()
    return card
end

-- CLEAR's look from its state: asking (SURE?, for D.CONFIRM seconds), and dimmed with nothing to clear or no editing.
local function PaintClear()
    local PS = Presets()
    local empty = PS.IsEmpty(card.fsIndex)
    if card.fsConfirm and (empty or (GetTime and GetTime() or 0) - card.fsConfirm >= D.CONFIRM) then card.fsConfirm = nil end
    if card.fsConfirm then
        StyleButton(card.clear, PINK, "SURE?", 9, { mix = 0.22, edgeA = 1 })
    else
        StyleButton(card.clear, PINK, "CLEAR", 9)
    end
    SetDisabled(card.clear, empty or PS.Refusal() ~= nil)
end

-- Repaints the card from the slot it edits (an unset slot shows no name and every element left out).
function Dial.RefreshCard()
    if not (card and card.fsIndex) then return end
    local PS = Presets()
    local preset = PS.Get(card.fsIndex)
    SeatCard()
    card.title:SetText("PRESET " .. card.fsIndex)
    card.name:SetText(preset and preset.name or "")
    local locked = PS.Refusal() ~= nil
    card.fsLocked = locked
    LockChooser(locked)
    card.name.fsDisabled = locked
    if card.name.SetEnabled then pcall(card.name.SetEnabled, card.name, not locked) end
    PaintName()
    local picks = preset and preset.picks or {}
    local order = ElementOrder(preset)
    local count = preset and #preset.order or 0
    for i, row in ipairs(card.rows) do
        local element = order[i]
        row.fsElement = element
        local c = ELEMENT[element] or WHITE
        local entry = PS.Entry(element, picks[element])
        local set = entry ~= nil
        row.fsSet = set
        row.tile.fsRing = c
        row.num:SetText(set and tostring(i) or "-")
        row.bar:SetColorTexture(c[1], c[2], c[3], 1)
        if set then
            row.tile.icon:SetTexture(entry.icon)
            row.tile.icon:SetVertexColor(1, 1, 1, entry.known and 1 or 0.4)
            row.tile.text:Hide()
            row.label:SetText((entry.name:gsub(" Totem$", "")) .. (entry.known and "" or " (L" .. entry.level .. ")"))
            Tint(row.label, entry.known and WHITE or MUTED)
        else
            row.tile.icon:SetColorTexture(0, 0, 0, 0)
            row.tile.icon:SetVertexColor(1, 1, 1, 1)
            Mono(row.tile.text, 9, MUTED)
            row.tile.text:SetText("--")
            row.tile.text:Show()
            row.label:SetText("left out")
            Tint(row.label, MUTED)
        end
        SetRowDisabled(row, locked)
        SetDisabled(row.up, locked)
        SetDisabled(row.down, locked)
        row.up:SetShown(set and i > 1)
        row.down:SetShown(set and i < count)
        PaintRow(row)
    end
    local colour = PS.Color(card.fsIndex)
    for i, sw in ipairs(card.swatches) do
        sw.fsSelected = i == colour
        SetSwatchDisabled(sw, locked)
    end
    PaintClear()
end

-- Opens the editor on slot `slot` (1 or 2, set or not; out of combat).
function Dial.OpenEditor(slot)
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    if slot ~= 1 and slot ~= 2 then return end
    BuildCard()
    card.fsIndex = slot
    card.fsConfirm = nil
    card:ClearAllPoints()
    local tb = Totems()
    local anchor
    for _, key in ipairs({ "preset2", "preset1" }) do
        local button = tb.Button(key)
        if not anchor and button and button:IsShown() then anchor = button end
    end
    anchor = anchor or tb.Button("preset1")
    card:SetPoint("BOTTOMRIGHT", anchor, "TOPRIGHT", 4.4 * Scale(), 21 * Scale())
    Dial.RefreshCard()
    card:Show()
end

-- Shift click on a cell: edits its preset. On an unset slot it makes the preset from the four totem buttons first (when
-- there is anything to copy) and opens the editor either way.
function Dial.EditSlot(slot)
    local PS = Presets()
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    local why = PS.Refusal()
    if why then return Refuse(why) end
    if not PS.Get(slot) then PS.Create(slot) end
    Dial.OpenEditor(slot)
end

function Dial.Card()
    return card
end

function Dial.Chooser()
    return chooser
end

-------------------------------------------------------------------------------
-- Repaint and the ticker
-------------------------------------------------------------------------------

function Dial.Refresh()
    local tb = Totems()
    if not (tb and tb.Button) then return end
    Presets().InvalidateKnown()
    for _, def in ipairs(tb.Cells and tb.Cells() or {}) do
        local button = tb.Button(def.key)
        if button and button.fsArcs and button:IsShown() then Paint(button) end
    end
    if card and card:IsShown() then Dial.RefreshCard() end
    local PS = Presets()
    if not pcall(PS.SyncSet2) then PS.Set2.state = "dead"; PS.Set2.why = "the set 2 sync raised" end
    PS.SaveState()
end

-- The ticker: the idle restart of a step, the open card following the refusal (it unlocks when "editable in a moment"
-- passes and locks if saving is lost) and CLEAR's question running out. Cells are painted by the events that change them.
local function Tick(self, elapsed)
    self.fsAcc = (self.fsAcc or 0) + (elapsed or 0)
    if self.fsAcc < D.TICK then return end
    self.fsAcc = 0
    local PS = Presets()
    PS.Expire()
    if not (card and card:IsShown()) then return end
    if card.fsLocked ~= (PS.Refusal() ~= nil) then
        Dial.RefreshCard()
    elseif card.fsConfirm then
        PaintClear()
    end
end

local function OnPresetEvent(what)
    if what == "step" or what == "edited" or what == "regen" or what == "set2" then
        local tb = Totems()
        for _, def in ipairs(tb and tb.Cells and tb.Cells() or {}) do
            local button = tb.Button(def.key)
            if button and button.fsArcs and button:IsShown() then Paint(button) end
        end
        if what == "edited" and card and card:IsShown() then Dial.RefreshCard() end
        Presets().SaveState()
    end
end

local function OnGameEvent(_, event, unit, _, spellId)
    local PS = Presets()
    if event == "UNIT_SPELLCAST_SUCCEEDED" then
        if unit == "player" then PS.OnCast(spellId) end
    elseif event == "PLAYER_REGEN_DISABLED" then
        Dial.CloseEditor()
    else
        PS.InvalidateKnown()        -- a learn event: the known totems may have changed
    end
end

local function Init()
    local PS = Presets()
    if not PS then return end
    PS.OnEvent(OnPresetEvent)
    local events = CreateFrame("Frame")
    events:RegisterEvent("UNIT_SPELLCAST_SUCCEEDED")
    events:RegisterEvent("PLAYER_REGEN_DISABLED")
    FS.FrameHelpers.RegisterEvents(events, { "SPELLS_CHANGED", "LEARNED_SPELL_IN_SKILL_LINE", "PLAYER_LEVEL_UP", "PLAYER_ENTERING_WORLD" })
    events:SetScript("OnEvent", OnGameEvent)
    local ticker = CreateFrame("Frame", "FSTotemDialTicker")
    ticker:SetScript("OnUpdate", Tick)
    if FS.Config and FS.Config.OnChange then
        local function Apply()
            local tb = Totems()
            if FS.ClassShoulder and FS.ClassShoulder.Refresh then pcall(FS.ClassShoulder.Refresh) end
            if tb and tb.Sync then tb.Sync() end
        end
        FS.Config.OnChange(PS.SETTINGS.preset1.key, Apply)
        FS.Config.OnChange(PS.SETTINGS.preset2.key, Apply)
        FS.Config.OnChange(PS.SETTINGS.plate.key, function() Dial.Refresh() end)
        FS.Config.OnChange(PS.SETTINGS.set2.key, function() Dial.Refresh() end)
    end
end
Init()
